/**
 * avatar.ts — procedural chibi avatar built purely from parametric Three.js
 * geometry. Faces +Z, feet rest on y = 0, total height ~2.7 units.
 * No external assets; every garment / hair / face variant has a distinct
 * silhouette generated by the builders below.
 */
import * as THREE from "three";
import { RoundedBoxGeometry } from "three/addons/geometries/RoundedBoxGeometry.js";
import type { AvatarConfig } from "./wardrobe";
import { DEFAULT_AVATAR, WARDROBE, isValidAvatar } from "./wardrobe";

/* ---------------------------------------------------------------- helpers */

/** Recursively dispose every geometry and material under an object. Shared
 *  so other modules can reuse it. */
export function disposeObject3D(root: THREE.Object3D): void {
  root.traverse((obj) => {
    const m = obj as THREE.Mesh;
    if (m.isMesh) {
      m.geometry.dispose();
      const mat = m.material;
      if (Array.isArray(mat)) mat.forEach((x) => x.dispose());
      else if (mat) mat.dispose();
    }
  });
}

interface MatOpts {
  roughness?: number;
  metalness?: number;
  emissive?: THREE.ColorRepresentation;
  emissiveIntensity?: number;
  transparent?: boolean;
  opacity?: number;
}

/** Bright matte material (soft toy look). */
function mat(color: THREE.ColorRepresentation, opts: MatOpts = {}): THREE.MeshStandardMaterial {
  return new THREE.MeshStandardMaterial({
    color,
    roughness: opts.roughness ?? 0.88,
    metalness: opts.metalness ?? 0.02,
    emissive: opts.emissive ?? 0x000000,
    emissiveIntensity: opts.emissiveIntensity ?? 1,
    transparent: opts.transparent ?? false,
    opacity: opts.opacity ?? 1,
  });
}

function mesh(
  geo: THREE.BufferGeometry,
  material: THREE.Material,
  x = 0,
  y = 0,
  z = 0,
): THREE.Mesh {
  const m = new THREE.Mesh(geo, material);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

function add<T extends THREE.Object3D>(parent: THREE.Object3D, obj: T, x = 0, y = 0, z = 0): T {
  obj.position.set(x, y, z);
  parent.add(obj);
  return obj;
}

function sph(r: number, color: THREE.ColorRepresentation, seg = 20, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.SphereGeometry(r, seg, Math.max(10, Math.floor(seg * 0.7))), mat(color, opts));
}
function box(w: number, h: number, d: number, color: THREE.ColorRepresentation, radius = 0.05, opts?: MatOpts): THREE.Mesh {
  return mesh(new RoundedBoxGeometry(w, h, d, 3, Math.min(radius, w / 3, h / 3, d / 3)), mat(color, opts));
}
function cyl(rt: number, rb: number, h: number, color: THREE.ColorRepresentation, seg = 20, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat(color, opts));
}
function cone(r: number, h: number, color: THREE.ColorRepresentation, seg = 16, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.ConeGeometry(r, h, seg), mat(color, opts));
}
function tor(r: number, tube: number, color: THREE.ColorRepresentation, arc = Math.PI * 2, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.TorusGeometry(r, tube, 10, 28, arc), mat(color, opts));
}
function cap(r: number, len: number, color: THREE.ColorRepresentation, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.CapsuleGeometry(r, len, 6, 16), mat(color, opts));
}

/** Flat 5-point star shape (for eyes / decorations). */
function starShape(outer: number, inner: number, points = 5): THREE.Shape {
  const s = new THREE.Shape();
  for (let i = 0; i < points * 2; i += 1) {
    const r = i % 2 === 0 ? outer : inner;
    const a = (i / (points * 2)) * Math.PI * 2 - Math.PI / 2;
    const x = Math.cos(a) * r;
    const y = Math.sin(a) * r;
    if (i === 0) s.moveTo(x, y);
    else s.lineTo(x, y);
  }
  s.closePath();
  return s;
}

/** Flat heart shape. */
function heartShape(size: number): THREE.Shape {
  const s = new THREE.Shape();
  const k = size;
  s.moveTo(0, -0.55 * k);
  s.bezierCurveTo(-1.1 * k, 0.25 * k, -0.55 * k, 1.0 * k, 0, 0.45 * k);
  s.bezierCurveTo(0.55 * k, 1.0 * k, 1.1 * k, 0.25 * k, 0, -0.55 * k);
  return s;
}

function flat(shape: THREE.Shape, color: THREE.ColorRepresentation, opts?: MatOpts): THREE.Mesh {
  return mesh(new THREE.ShapeGeometry(shape, 12), mat(color, { ...opts, roughness: 0.7 }));
}

/** Lookup the display color of a wardrobe item. */
function itemColor(slot: keyof AvatarConfig, id: string, fallback: string): string {
  return WARDROBE[slot].find((i) => i.id === id)?.color ?? fallback;
}

/* ------------------------------------------------------------- proportions */

const HIP_Y = 0.94; // hip pivot height; feet end at y = 0
const HEAD_R = 0.6;
const HEAD_CY = 0.44; // head center inside the head group

interface BaseSpec {
  armX: number; // shoulder pivot offset
  torsoW: number; // torso x scale
  hipW: number; // leg spread
  scale: number; // overall height scale
}

const BASES: Record<string, BaseSpec> = {
  base_girl: { armX: 0.33, torsoW: 0.95, hipW: 0.165, scale: 0.96 },
  base_boy: { armX: 0.4, torsoW: 1.14, hipW: 0.15, scale: 1.0 },
  base_neutral: { armX: 0.36, torsoW: 1.04, hipW: 0.155, scale: 0.98 },
};

/* ------------------------------------------------------------------ class */

export class Avatar {
  readonly root = new THREE.Group();

  private config: AvatarConfig;
  private rig: THREE.Group | null = null;

  // animated part references (re-assigned on every build)
  private body!: THREE.Group;
  private headG!: THREE.Group;
  private armL!: THREE.Group;
  private armR!: THREE.Group;
  private legL!: THREE.Group;
  private legR!: THREE.Group;
  private torsoM!: THREE.Mesh;

  private jumpBlend = 0;

  constructor(config: AvatarConfig) {
    this.config = isValidAvatar(config) ? { ...config } : { ...DEFAULT_AVATAR };
    this.root.name = "avatar";
    this.build();
  }

  setConfig(config: AvatarConfig): void {
    if (!isValidAvatar(config)) return;
    this.config = { ...config };
    this.build();
  }

  /** Walk / idle / jump posing. `time` in seconds, `speed` in units/s. Never
   *  allocates: only writes transforms of pre-built nodes. */
  update(time: number, speed: number, grounded: boolean): void {
    if (!this.rig) return;
    const s = Math.min(Math.abs(speed) / 5, 1);
    const phase = time * (4 + Math.abs(speed) * 1.1);
    const swing = Math.sin(phase) * (0.02 + 0.75 * s);

    this.jumpBlend += ((grounded ? 0 : 1) - this.jumpBlend) * 0.18;
    const j = this.jumpBlend;
    const g = 1 - j;

    // legs: walk swing, tucked while airborne
    this.legL.rotation.x = -swing * g + j * -0.55;
    this.legR.rotation.x = swing * g + j * 0.4;
    // arms: counter-swing, raised while airborne
    this.armL.rotation.x = swing * 0.9 * g;
    this.armR.rotation.x = -swing * 0.9 * g;
    this.armL.rotation.z = 0.1 + j * 0.95;
    this.armR.rotation.z = -0.1 - j * 0.95;

    // body: run lean + step bob + idle sway
    this.rig.rotation.x = s * 0.1 * g;
    this.rig.position.y = Math.abs(Math.sin(phase)) * 0.055 * s * g;
    this.rig.rotation.z = Math.sin(time * 1.7) * 0.02 * (1 - s) * g;

    // breathing (torso squash) + gentle head motion
    const breath = 1 + Math.sin(time * 2.3) * 0.02 * (1 - s * 0.6);
    this.torsoM.scale.y = breath;
    this.headG.rotation.z = Math.sin(time * 1.6) * 0.035 * (1 - s);
    this.headG.rotation.x = j * 0.18 - s * 0.06;
  }

  dispose(): void {
    if (this.root.parent) this.root.parent.remove(this.root);
    disposeObject3D(this.root);
    this.root.clear();
    this.rig = null;
  }

  /* -------------------------------------------------------------- build */

  private build(): void {
    if (this.rig) {
      this.root.remove(this.rig);
      disposeObject3D(this.rig);
    }
    this.root.scale.setScalar(1);

    const cfg = this.config;
    const base = BASES[cfg.base] ?? BASES.base_neutral;
    const skin = itemColor("skin", cfg.skin, "#ffdcc4");
    const hairCol = itemColor("hairColor", cfg.hairColor, "#6b4226");

    this.root.scale.setScalar(base.scale);

    const rig = new THREE.Group();
    this.rig = rig;
    this.root.add(rig);

    this.body = add(rig, new THREE.Group(), 0, HIP_Y, 0);

    // legs (pivot at hip)
    this.legL = add(this.body, new THREE.Group(), -base.hipW, 0, 0);
    this.legR = add(this.body, new THREE.Group(), base.hipW, 0, 0);
    this.buildLeg(this.legL, skin, cfg);
    this.buildLeg(this.legR, skin, cfg);

    // pelvis filler (mostly hidden by bottoms)
    const pelvis = sph(0.26, skin, 18);
    pelvis.scale.set(base.torsoW, 0.72, 0.88);
    add(this.body, pelvis, 0, 0, 0);

    // torso
    this.torsoM = cap(0.3, 0.34, skin);
    this.torsoM.scale.set(base.torsoW, 1, 0.92);
    add(this.body, this.torsoM, 0, 0.35, 0);

    // neck
    add(this.body, cyl(0.09, 0.1, 0.16, skin, 14), 0, 0.72, 0);

    // arms (pivot at shoulder)
    this.armL = add(this.body, new THREE.Group(), -base.armX, 0.52, 0);
    this.armR = add(this.body, new THREE.Group(), base.armX, 0.52, 0);
    this.armL.rotation.z = 0.1;
    this.armR.rotation.z = -0.1;
    const sleeve = this.sleeveStyle(cfg.top);
    this.buildArm(this.armL, skin, sleeve, cfg);
    this.buildArm(this.armR, skin, sleeve, cfg);

    // head
    this.headG = add(this.body, new THREE.Group(), 0, 0.7, 0);
    add(this.headG, sph(HEAD_R, skin, 32), 0, HEAD_CY, 0);
    const face = add(this.headG, new THREE.Group(), 0, HEAD_CY, 0);
    this.buildFace(face, cfg);
    this.buildHair(this.headG, hairCol, cfg);
    this.buildHat(this.headG, cfg);

    // garments & extras
    this.buildTop(this.body, cfg, base);
    this.buildBottom(this.body, this.legL, this.legR, cfg, base);
    this.buildAccessory(this.body, this.armR, this.headG, cfg);
  }

  private sleeveStyle(topId: string): "none" | "short" | "long" | "wide" {
    switch (topId) {
      case "top_jersey":
        return "none";
      case "top_tee":
      case "top_sailor":
      case "top_apron":
        return "short";
      case "top_hanfu":
      case "top_daorobe":
        return "wide";
      default:
        return "long";
    }
  }

  /* ------------------------------------------------------------- limbs */

  private buildLeg(leg: THREE.Group, skin: string, cfg: AvatarConfig): void {
    add(leg, cap(0.125, 0.5, skin), 0, -0.4, 0);
    const foot = add(leg, new THREE.Group(), 0, -0.788, 0.02);
    this.buildShoe(foot, cfg.shoes);
  }

  private buildArm(
    arm: THREE.Group,
    skin: string,
    sleeve: "none" | "short" | "long" | "wide",
    cfg: AvatarConfig,
  ): void {
    add(arm, cap(0.105, 0.3, skin), 0, -0.2, 0);
    add(arm, sph(0.13, skin, 16), 0, -0.48, 0); // hand
    const col = this.topColor(cfg.top);
    if (sleeve === "short") {
      add(arm, cap(0.14, 0.06, col), 0, -0.06, 0);
    } else if (sleeve === "long") {
      add(arm, cap(0.13, 0.26, col), 0, -0.2, 0);
      add(arm, tor(0.12, 0.03, col), 0, -0.4, 0).rotation.x = Math.PI / 2;
    } else if (sleeve === "wide") {
      const s = cone(0.24, 0.42, col, 18);
      s.rotation.x = Math.PI; // flare downward
      add(arm, s, 0, -0.26, 0);
      const trim = tor(0.22, 0.025, "#ffffff");
      trim.rotation.x = Math.PI / 2;
      add(arm, trim, 0, -0.45, 0);
    } else {
      // sleeveless: small shoulder ring trim
      const trim = tor(0.115, 0.025, "#ffffff");
      trim.rotation.x = Math.PI / 2;
      add(arm, trim, 0, -0.05, 0);
    }
  }

  /* -------------------------------------------------------------- face */

  private buildFace(face: THREE.Group, cfg: AvatarConfig): void {
    const ink = "#33262b";
    // blush
    for (const sx of [-1, 1]) {
      const b = sph(0.075, "#ff9db1", 12);
      b.scale.set(1, 0.55, 0.35);
      add(face, b, sx * 0.32, -0.08, 0.47).rotation.y = sx * 0.55;
    }
    // tiny nose
    const nose = sph(0.03, "#f2b09a", 10);
    nose.scale.set(1, 0.8, 0.6);
    add(face, nose, 0, -0.06, 0.6);

    for (const sx of [-1, 1]) {
      const eye = add(face, new THREE.Group(), sx * 0.215, 0.05, 0.545);
      eye.rotation.y = sx * 0.22;
      this.buildEye(eye, cfg.eyes, sx, ink);
    }
    const mouth = add(face, new THREE.Group(), 0, -0.2, 0.555);
    this.buildMouth(mouth, cfg.mouth, ink);
  }

  /** Each eye style has its own geometry; `sx` is -1 (left) / +1 (right). */
  private buildEye(g: THREE.Group, id: string, sx: number, ink: string): void {
    switch (id) {
      case "eyes_smile": {
        const arc = tor(0.07, 0.018, ink, Math.PI);
        add(g, arc, 0, 0, 0.01);
        break;
      }
      case "eyes_star": {
        add(g, flat(starShape(0.085, 0.038), "#f5b942", { emissive: "#f5b942", emissiveIntensity: 0.35 }), 0, 0, 0.012);
        add(g, flat(starShape(0.04, 0.018), "#fff7e0"), 0.01, 0.01, 0.02);
        break;
      }
      case "eyes_sleepy": {
        const lid = sph(0.075, ink, 12);
        lid.scale.set(1, 0.32, 0.35);
        add(g, lid, 0, 0.01, 0.005);
        for (const lx of [-0.06, 0, 0.06]) {
          const lash = box(0.014, 0.05, 0.012, ink, 0.005);
          lash.rotation.z = lx * 4;
          add(g, lash, lx, -0.045, 0.01);
        }
        break;
      }
      case "eyes_sharp": {
        const almond = sph(0.085, ink, 14);
        almond.scale.set(1.05, 0.62, 0.35);
        add(g, almond, 0, 0, 0.004).rotation.z = sx * -0.35;
        const hl = sph(0.024, "#ffffff", 8);
        hl.scale.set(1, 1, 0.4);
        add(g, hl, 0.02, 0.02, 0.03);
        const brow = box(0.13, 0.025, 0.02, ink, 0.008);
        brow.rotation.z = sx * -0.3;
        add(g, brow, 0, 0.115, 0.0);
        break;
      }
      case "eyes_wink": {
        if (sx < 0) {
          const arc = tor(0.065, 0.017, ink, Math.PI);
          add(g, arc, 0, 0, 0.01);
        } else {
          const ball = sph(0.075, ink, 14);
          ball.scale.set(1, 1, 0.4);
          add(g, ball, 0, 0, 0.004);
          const hl = sph(0.026, "#ffffff", 8);
          hl.scale.set(1, 1, 0.4);
          add(g, hl, 0.025, 0.03, 0.035);
        }
        break;
      }
      case "eyes_heart": {
        const h = flat(heartShape(0.085), "#ff5f7e", { emissive: "#ff5f7e", emissiveIntensity: 0.25 });
        add(g, h, 0, 0, 0.012);
        break;
      }
      case "eyes_cat": {
        const white = sph(0.095, "#fff8ec", 14);
        white.scale.set(0.95, 1.05, 0.35);
        add(g, white, 0, 0, 0);
        const pupil = sph(0.045, "#3f8f5f", 12);
        pupil.scale.set(0.55, 1.15, 0.3);
        add(g, pupil, 0, 0, 0.035);
        const hl = sph(0.018, "#ffffff", 8);
        hl.scale.set(1, 1, 0.4);
        add(g, hl, 0.02, 0.045, 0.055);
        break;
      }
      case "eyes_round":
      default: {
        const ball = sph(0.08, ink, 16);
        ball.scale.set(1, 1.12, 0.4);
        add(g, ball, 0, 0, 0.004);
        const hl = sph(0.028, "#ffffff", 8);
        hl.scale.set(1, 1, 0.4);
        add(g, hl, 0.026, 0.032, 0.038);
        const hl2 = sph(0.014, "#ffffff", 8);
        hl2.scale.set(1, 1, 0.4);
        add(g, hl2, -0.02, -0.025, 0.038);
        break;
      }
    }
  }

  private buildMouth(g: THREE.Group, id: string, ink: string): void {
    switch (id) {
      case "mouth_grin": {
        const m = box(0.17, 0.09, 0.03, "#7a3b3b", 0.02);
        add(g, m, 0, -0.01, 0.008);
        const teeth = box(0.15, 0.045, 0.02, "#ffffff", 0.015);
        add(g, teeth, 0, 0.012, 0.022);
        break;
      }
      case "mouth_o": {
        const o = sph(0.05, "#7a3b3b", 12);
        o.scale.set(1, 1.15, 0.4);
        add(g, o, 0, -0.01, 0.01);
        break;
      }
      case "mouth_cat": {
        for (const sx of [-1, 1]) {
          const arc = tor(0.045, 0.013, ink, Math.PI * 0.9);
          arc.rotation.z = Math.PI + sx * 0.35 - 0.35;
          add(g, arc, sx * 0.045, 0.01, 0.012);
        }
        break;
      }
      case "mouth_flat": {
        add(g, box(0.11, 0.02, 0.02, ink, 0.008), 0, 0, 0.012);
        break;
      }
      case "mouth_open": {
        const o = sph(0.085, "#8a4040", 14);
        o.scale.set(1.15, 0.75, 0.35);
        add(g, o, 0, -0.02, 0.006);
        const tongue = sph(0.05, "#ff8f9f", 10);
        tongue.scale.set(1, 0.5, 0.3);
        add(g, tongue, 0, -0.045, 0.03);
        break;
      }
      case "mouth_smile":
      default: {
        const arc = tor(0.06, 0.015, ink, Math.PI);
        arc.rotation.z = Math.PI;
        add(g, arc, 0, 0.015, 0.012);
        break;
      }
    }
  }

  /* -------------------------------------------------------------- hair */

  /** Hair styles: each variant changes silhouette, not just color. All
   *  coordinates are relative to the head center. */
  private buildHair(headG: THREE.Group, color: string, cfg: AvatarConfig): void {
    const g = add(headG, new THREE.Group(), 0, HEAD_CY, 0);
    const fringe = () => {
      const f = box(0.66, 0.2, 0.24, color, 0.09);
      f.rotation.x = -0.32;
      add(g, f, 0, 0.34, 0.44);
    };
    const hairCap = (theta: number, tilt = -0.45) => {
      const c = mesh(new THREE.SphereGeometry(0.64, 32, 20, 0, Math.PI * 2, 0, theta), mat(color));
      c.rotation.x = tilt;
      add(g, c, 0, 0.02, 0);
      return c;
    };

    switch (cfg.hair) {
      case "hair_bob": {
        hairCap(2.15, -0.35);
        fringe();
        for (const sx of [-1, 1]) {
          const side = sph(0.24, color, 16);
          side.scale.set(0.65, 1.25, 0.9);
          add(g, side, sx * 0.52, -0.12, 0.08);
        }
        break;
      }
      case "hair_twintail": {
        hairCap(1.85);
        fringe();
        for (const sx of [-1, 1]) {
          add(g, sph(0.17, color, 14), sx * 0.6, 0.42, -0.12);
          const tail = cap(0.13, 0.5, color);
          tail.rotation.z = sx * 0.5;
          tail.rotation.x = 0.15;
          add(g, tail, sx * 0.72, -0.02, -0.12);
          const tie = tor(0.1, 0.03, "#ff7d9c");
          tie.rotation.x = Math.PI / 2;
          add(g, tie, sx * 0.62, 0.3, -0.12);
        }
        break;
      }
      case "hair_short": {
        hairCap(1.55, -0.4);
        fringe();
        break;
      }
      case "hair_ponytail": {
        hairCap(1.8);
        fringe();
        add(g, sph(0.16, color, 14), 0, 0.62, -0.42);
        const tail = cap(0.14, 0.55, color);
        tail.rotation.x = 0.55;
        add(g, tail, 0, 0.28, -0.68);
        const tie = tor(0.09, 0.03, "#ffd23f");
        tie.rotation.x = Math.PI / 2 - 0.4;
        add(g, tie, 0, 0.55, -0.48);
        break;
      }
      case "hair_long": {
        hairCap(1.9, -0.4);
        fringe();
        const back = box(0.85, 1.35, 0.28, color, 0.12);
        add(g, back, 0, -0.55, -0.5);
        for (const sx of [-1, 1]) {
          const strand = cap(0.09, 0.6, color);
          add(g, strand, sx * 0.52, -0.3, 0.3);
        }
        break;
      }
      case "hair_hime": {
        hairCap(1.75, -0.42);
        add(g, box(0.62, 0.16, 0.2, color, 0.06), 0, 0.26, 0.5); // straight fringe
        for (const sx of [-1, 1]) {
          add(g, box(0.16, 0.68, 0.26, color, 0.06), sx * 0.56, -0.14, 0.22);
        }
        const back = box(0.8, 0.9, 0.24, color, 0.1);
        add(g, back, 0, -0.35, -0.5);
        break;
      }
      case "hair_buns": {
        hairCap(1.8);
        fringe();
        for (const sx of [-1, 1]) {
          add(g, sph(0.26, color, 16), sx * 0.42, 0.62, -0.05);
          const tie = tor(0.14, 0.03, "#ff9d5c");
          tie.rotation.x = Math.PI / 2;
          add(g, tie, sx * 0.42, 0.48, -0.05);
        }
        break;
      }
      case "hair_curly": {
        hairCap(1.5, -0.4);
        const puffs: [number, number, number, number][] = [
          [0, 0.62, -0.15, 0.3], [-0.42, 0.45, -0.2, 0.28], [0.42, 0.45, -0.2, 0.28],
          [-0.55, 0.05, -0.15, 0.26], [0.55, 0.05, -0.15, 0.26], [0, 0.3, -0.5, 0.3],
          [-0.3, 0.6, -0.4, 0.24], [0.3, 0.6, -0.4, 0.24],
        ];
        for (const [x, y, z, r] of puffs) add(g, sph(r, color, 14), x, y, z);
        fringe();
        break;
      }
      case "hair_sidebraid": {
        hairCap(1.85, -0.42);
        fringe();
        let y = 0.1;
        let z = 0.42;
        for (let i = 0; i < 4; i += 1) {
          add(g, sph(0.15 - i * 0.018, color, 12), 0.52, y, z);
          y -= 0.24;
          z -= 0.03;
        }
        add(g, cone(0.07, 0.16, "#6ec6c0", 10), 0.52, y - 0.05, z).rotation.x = Math.PI;
        break;
      }
      case "hair_messy": {
        hairCap(1.6, -0.42);
        const spikes: [number, number, number, number][] = [
          [0, 0.72, 0.05, 0.4], [-0.3, 0.6, 0.1, -0.5], [0.32, 0.58, 0.05, 0.5],
          [-0.15, 0.62, -0.35, -0.2], [0.18, 0.6, -0.35, 0.25], [0, 0.55, 0.35, 0],
        ];
        for (const [x, y, z, rz] of spikes) {
          const s = cone(0.12, 0.4, color, 8);
          s.rotation.z = rz;
          s.rotation.x = z > 0.2 ? -0.5 : 0.15;
          add(g, s, x, y, z);
        }
        fringe();
        break;
      }
      case "hair_spiky": {
        hairCap(1.45, -0.42);
        for (let i = 0; i < 7; i += 1) {
          const a = (i / 6 - 0.5) * Math.PI * 1.1;
          const s = cone(0.13, 0.5 + 0.14 * Math.cos(a), color, 8);
          s.rotation.z = -a * 0.8;
          add(g, s, Math.sin(a) * 0.42, 0.62 + 0.08 * Math.cos(a), -0.05);
        }
        break;
      }
      case "hair_afro": {
        const afro = sph(0.74, color, 24);
        afro.scale.set(1, 0.95, 1);
        add(g, afro, 0, 0.18, -0.16);
        break;
      }
      default: {
        hairCap(1.8);
        fringe();
        break;
      }
    }
  }

  /* ----------------------------------------------------------- garments */

  private topColor(id: string): string {
    return itemColor("top", id, "#7ec8f2");
  }

  private buildTop(body: THREE.Group, cfg: AvatarConfig, base: BaseSpec): void {
    const id = cfg.top;
    const col = this.topColor(id);
    const g = add(body, new THREE.Group(), 0, 0, 0);

    // torso shell (every top has one; silhouette details added per style)
    const shell = cap(0.33, 0.34, col);
    shell.scale.set(base.torsoW * 1.04, 1.0, 0.98);
    add(g, shell, 0, 0.35, 0);

    switch (id) {
      case "top_tee": {
        // cloud decal
        add(g, sph(0.075, "#ffffff", 12), -0.06, 0.42, 0.32);
        add(g, sph(0.09, "#ffffff", 12), 0.03, 0.45, 0.32);
        add(g, sph(0.07, "#ffffff", 12), 0.11, 0.41, 0.31);
        const hem = tor(0.32, 0.025, "#ffffff");
        hem.rotation.x = Math.PI / 2;
        hem.scale.set(base.torsoW, 1, 1);
        add(g, hem, 0, 0.08, 0);
        break;
      }
      case "top_hoodie": {
        const hood = mesh(new THREE.SphereGeometry(0.26, 18, 12, 0, Math.PI * 2, 0, Math.PI / 2), mat(col));
        hood.rotation.x = -0.9;
        add(g, hood, 0, 0.66, -0.24);
        add(g, box(0.34, 0.16, 0.1, col, 0.05), 0, 0.14, 0.3); // kangaroo pocket
        for (const sx of [-1, 1]) add(g, cyl(0.015, 0.015, 0.16, "#ffffff", 8), sx * 0.08, 0.52, 0.33);
        break;
      }
      case "top_uniform": {
        for (const sx of [-1, 1]) {
          const flap = box(0.22, 0.14, 0.04, "#f4f0e4", 0.015);
          flap.rotation.z = sx * 0.6;
          flap.rotation.x = -0.25;
          add(g, flap, sx * 0.13, 0.6, 0.27);
        }
        const tie = box(0.09, 0.28, 0.03, "#c94f4f", 0.015);
        tie.rotation.x = -0.12;
        add(g, tie, 0, 0.42, 0.33);
        for (let i = 0; i < 3; i += 1) add(g, sph(0.025, "#f2c14e", 8), 0, 0.3 - i * 0.11, 0.345);
        break;
      }
      case "top_sweater": {
        const collar = tor(0.15, 0.05, col);
        collar.rotation.x = Math.PI / 2;
        add(g, collar, 0, 0.68, 0);
        for (const y of [0.22, 0.38]) {
          const stripe = tor(0.335, 0.02, "#fff4dc");
          stripe.rotation.x = Math.PI / 2;
          stripe.scale.set(base.torsoW, 1, 1);
          add(g, stripe, 0, y, 0);
        }
        break;
      }
      case "top_spacesuit": {
        add(g, box(0.34, 0.26, 0.08, "#e8ecf5", 0.03), 0, 0.42, 0.3);
        add(g, sph(0.03, "#ff6b6b", 8), -0.09, 0.46, 0.35);
        add(g, sph(0.03, "#5cc8ff", 8), 0, 0.46, 0.35);
        add(g, sph(0.03, "#72d6a0", 8), 0.09, 0.46, 0.35);
        const belt = tor(0.335, 0.04, "#8a92a8");
        belt.rotation.x = Math.PI / 2;
        belt.scale.set(base.torsoW, 1, 1);
        add(g, belt, 0, 0.08, 0);
        for (const sx of [-1, 1]) add(g, sph(0.14, "#c5cbdb", 14), sx * base.armX, 0.58, 0);
        break;
      }
      case "top_starjacket": {
        add(g, box(0.05, 0.56, 0.04, "#f2e6c8", 0.015), 0, 0.34, 0.335); // zipper
        add(g, flat(starShape(0.08, 0.035), "#ffd23f", { emissive: "#ffd23f", emissiveIntensity: 0.4 }), -0.17, 0.48, 0.33);
        add(g, flat(starShape(0.055, 0.024), "#9fd8ff"), 0.16, 0.26, 0.335);
        for (const sx of [-1, 1]) add(g, box(0.16, 0.05, 0.14, "#f2c14e", 0.02), sx * base.armX, 0.62, 0);
        break;
      }
      case "top_hanfu": {
        for (const sx of [-1, 1]) {
          const collar = box(0.3, 0.09, 0.04, "#fff4ec", 0.02);
          collar.rotation.z = sx * 0.65;
          collar.rotation.x = -0.2;
          add(g, collar, sx * 0.1, 0.55, 0.28);
        }
        const sash = tor(0.33, 0.05, "#c96a7e");
        sash.rotation.x = Math.PI / 2;
        sash.scale.set(base.torsoW, 1, 1);
        add(g, sash, 0, 0.12, 0);
        add(g, box(0.12, 0.2, 0.05, "#c96a7e", 0.02), 0, -0.02, 0.3); // sash knot tails
        break;
      }
      case "top_daorobe": {
        const robe = cyl(0.36, 0.52, 0.55, col, 22);
        robe.scale.set(base.torsoW, 1, 0.9);
        add(g, robe, 0, -0.2, 0);
        add(g, box(0.08, 0.6, 0.03, "#f4f0e4", 0.015), 0, 0.32, 0.33); // front placket
        const trim = tor(0.5, 0.025, "#f4f0e4");
        trim.rotation.x = Math.PI / 2;
        trim.scale.set(base.torsoW, 1, 0.9);
        add(g, trim, 0, -0.46, 0);
        break;
      }
      case "top_sailor": {
        const collarBack = box(0.5, 0.34, 0.04, "#3f6ea8", 0.02);
        collarBack.rotation.x = 0.35;
        add(g, collarBack, 0, 0.52, -0.28);
        for (const sx of [-1, 1]) {
          const v = box(0.2, 0.05, 0.04, "#3f6ea8", 0.015);
          v.rotation.z = sx * 0.5;
          v.rotation.x = -0.2;
          add(g, v, sx * 0.11, 0.55, 0.29);
        }
        const scarf = cone(0.07, 0.16, "#e85c5c", 10);
        scarf.rotation.x = Math.PI - 0.15;
        add(g, scarf, 0, 0.48, 0.32);
        break;
      }
      case "top_apron": {
        add(g, box(0.44, 0.5, 0.05, "#fffaf0", 0.04), 0, 0.22, 0.3); // apron front
        for (const sx of [-1, 1]) {
          const strap = box(0.07, 0.3, 0.03, "#fffaf0", 0.015);
          strap.rotation.z = sx * 0.25;
          add(g, strap, sx * 0.14, 0.56, 0.28);
        }
        add(g, box(0.24, 0.14, 0.06, "#f5d9a8", 0.03), 0, 0.18, 0.34); // pocket
        add(g, sph(0.035, "#c96a4f", 8), 0, 0.47, 0.33); // neck button
        break;
      }
      case "top_dinohoodie": {
        const belly = sph(0.24, "#d8f0b8", 16);
        belly.scale.set(1, 1.25, 0.45);
        add(g, belly, 0, 0.3, 0.26);
        for (let i = 0; i < 3; i += 1) {
          const spike = cone(0.06, 0.14, "#4f8f3f", 8);
          spike.rotation.x = -0.5;
          add(g, spike, 0, 0.62 - i * 0.22, -0.3 - i * 0.02);
        }
        const hood = mesh(new THREE.SphereGeometry(0.24, 18, 12, 0, Math.PI * 2, 0, Math.PI / 2), mat(col));
        hood.rotation.x = -0.9;
        add(g, hood, 0, 0.64, -0.22);
        break;
      }
      case "top_jersey": {
        const neck = tor(0.14, 0.03, "#ffffff");
        neck.rotation.x = Math.PI / 2;
        add(g, neck, 0, 0.66, 0);
        const num = mesh(new THREE.CircleGeometry(0.12, 20), mat("#ffffff"));
        add(g, num, 0, 0.38, 0.335);
        const inner = mesh(new THREE.CircleGeometry(0.08, 20), mat(col));
        add(g, inner, 0, 0.38, 0.34);
        const hem = tor(0.33, 0.025, "#ffffff");
        hem.rotation.x = Math.PI / 2;
        hem.scale.set(base.torsoW, 1, 1);
        add(g, hem, 0, 0.06, 0);
        break;
      }
      default:
        break;
    }
  }

  private buildBottom(
    body: THREE.Group,
    legL: THREE.Group,
    legR: THREE.Group,
    cfg: AvatarConfig,
    base: BaseSpec,
  ): void {
    const id = cfg.bottom;
    const col = itemColor("bottom", id, "#5a7fb8");
    const legs = [legL, legR];

    const pantLegs = (r: number, len: number, y: number, color: string) => {
      for (const leg of legs) add(leg, cap(r, len, color), 0, y, 0);
    };

    switch (id) {
      case "bottom_jeans": {
        pantLegs(0.155, 0.42, -0.36, col);
        for (const leg of legs) {
          const cuff = tor(0.15, 0.025, "#8fa8cc");
          cuff.rotation.x = Math.PI / 2;
          add(leg, cuff, 0, -0.62, 0);
        }
        add(body, box(0.2, 0.1, 0.05, "#4a6a9e", 0.02), 0, 0.02, 0.26); // button fly patch
        break;
      }
      case "bottom_shorts": {
        pantLegs(0.165, 0.14, -0.2, col);
        const waist = tor(0.3, 0.03, "#b8924f");
        waist.rotation.x = Math.PI / 2;
        waist.scale.set(base.torsoW, 1, 0.95);
        add(body, waist, 0, -0.02, 0);
        break;
      }
      case "bottom_pleated": {
        const skirt = cyl(0.32, 0.52, 0.42, col, 24);
        skirt.scale.set(base.torsoW, 1, 0.92);
        add(body, skirt, 0, -0.18, 0);
        for (let i = 0; i < 8; i += 1) {
          const a = (i / 8) * Math.PI * 2;
          const pleat = box(0.05, 0.4, 0.05, "#77518c", 0.015);
          pleat.rotation.z = Math.sin(a) * 0.18;
          pleat.rotation.x = Math.cos(a) * 0.18;
          add(body, pleat, Math.sin(a) * 0.42 * base.torsoW, -0.2, Math.cos(a) * 0.4);
        }
        break;
      }
      case "bottom_trousers": {
        pantLegs(0.15, 0.52, -0.42, col);
        const waist = tor(0.3, 0.03, "#3a3a44");
        waist.rotation.x = Math.PI / 2;
        waist.scale.set(base.torsoW, 1, 0.95);
        add(body, waist, 0, -0.02, 0);
        break;
      }
      case "bottom_spacepants": {
        pantLegs(0.16, 0.5, -0.42, col);
        for (const leg of legs) {
          const knee = sph(0.13, "#8a92a8", 12);
          knee.scale.set(1, 0.8, 0.7);
          add(leg, knee, 0, -0.42, 0.1);
        }
        add(body, box(0.24, 0.12, 0.06, "#8a92a8", 0.03), 0, 0.0, 0.27); // utility buckle
        break;
      }
      case "bottom_longskirt": {
        const skirt = cyl(0.32, 0.56, 0.92, col, 26);
        skirt.scale.set(base.torsoW, 1, 0.92);
        add(body, skirt, 0, -0.44, 0);
        const waist = tor(0.31, 0.045, "#c96a7e");
        waist.rotation.x = Math.PI / 2;
        waist.scale.set(base.torsoW, 1, 1);
        add(body, waist, 0, 0.0, 0);
        const hem = tor(0.55, 0.03, "#f6d8de");
        hem.rotation.x = Math.PI / 2;
        hem.scale.set(base.torsoW, 1, 0.92);
        add(body, hem, 0, -0.88, 0);
        break;
      }
      case "bottom_beach": {
        pantLegs(0.165, 0.16, -0.22, col);
        const dots: [number, number, number, string][] = [
          [-0.1, -0.18, 0.16, "#ffffff"], [0.12, -0.26, 0.15, "#ffe28a"], [0.02, -0.3, -0.17, "#ffffff"],
        ];
        for (const [x, y, z, c] of dots) {
          const d = sph(0.04, c, 8);
          d.scale.set(1, 1, 0.4);
          add(legs[0], d, x, y + 0.0, z);
        }
        break;
      }
      case "bottom_bloomers": {
        for (const leg of legs) {
          const puff = sph(0.21, col, 16);
          puff.scale.set(1, 0.85, 1);
          add(leg, puff, 0, -0.22, 0);
          const cuff = tor(0.13, 0.03, "#fff4dc");
          cuff.rotation.x = Math.PI / 2;
          add(leg, cuff, 0, -0.38, 0);
        }
        const waist = tor(0.3, 0.04, "#fff4dc");
        waist.rotation.x = Math.PI / 2;
        waist.scale.set(base.torsoW, 1, 1);
        add(body, waist, 0, -0.02, 0);
        break;
      }
      case "bottom_dinopants": {
        pantLegs(0.16, 0.46, -0.4, col);
        // small tail tapering behind
        let z = -0.28;
        let y = -0.05;
        for (let i = 0; i < 3; i += 1) {
          add(body, sph(0.14 - i * 0.035, col, 12), 0, y, z);
          z -= 0.16;
          y -= 0.05;
        }
        break;
      }
      case "bottom_sportshorts": {
        pantLegs(0.16, 0.16, -0.22, col);
        for (const leg of legs) {
          add(leg, box(0.03, 0.2, 0.2, "#ffffff", 0.01), leg === legL ? -0.16 : 0.16, -0.22, 0);
        }
        const waist = tor(0.3, 0.035, "#ffffff");
        waist.rotation.x = Math.PI / 2;
        waist.scale.set(base.torsoW, 1, 0.95);
        add(body, waist, 0, -0.02, 0);
        break;
      }
      default:
        break;
    }
  }

  /* -------------------------------------------------------------- shoes */

  private buildShoe(foot: THREE.Group, id: string): void {
    const col = itemColor("shoes", id, "#ffffff");
    switch (id) {
      case "shoes_sneakers": {
        add(foot, box(0.24, 0.07, 0.38, "#ffffff", 0.03), 0, -0.105, 0.05);
        add(foot, box(0.22, 0.12, 0.32, col, 0.05), 0, -0.02, 0.04);
        const toe = sph(0.09, "#f2e6d8", 12);
        toe.scale.set(1.1, 0.7, 1);
        add(foot, toe, 0, -0.05, 0.19);
        add(foot, box(0.16, 0.02, 0.1, "#e85c5c", 0.008), 0, 0.045, 0.06); // lace bar
        break;
      }
      case "shoes_loafers": {
        add(foot, box(0.22, 0.05, 0.34, "#3a2a1e", 0.02), 0, -0.115, 0.04);
        add(foot, box(0.21, 0.1, 0.3, col, 0.045), 0, -0.04, 0.03);
        add(foot, box(0.14, 0.02, 0.05, "#c9a06a", 0.008), 0, 0.02, 0.1);
        break;
      }
      case "shoes_spaceboots": {
        add(foot, box(0.26, 0.08, 0.4, "#8a92a8", 0.03), 0, -0.1, 0.05);
        add(foot, cyl(0.15, 0.16, 0.24, col, 16), 0, 0.04, 0);
        const toe = sph(0.12, col, 12);
        toe.scale.set(1, 0.65, 1.2);
        add(foot, toe, 0, -0.045, 0.16);
        const ring = tor(0.15, 0.02, "#5cc8ff", Math.PI * 2, { emissive: "#5cc8ff", emissiveIntensity: 0.5 });
        ring.rotation.x = Math.PI / 2;
        add(foot, ring, 0, 0.12, 0);
        break;
      }
      case "shoes_cloth": {
        add(foot, box(0.22, 0.04, 0.32, "#f4f0e4", 0.02), 0, -0.12, 0.04);
        add(foot, box(0.2, 0.09, 0.28, col, 0.04), 0, -0.055, 0.03);
        const tip = sph(0.07, col, 10);
        tip.scale.set(1, 0.6, 1);
        add(foot, tip, 0, -0.04, 0.17);
        break;
      }
      case "shoes_sandals": {
        add(foot, box(0.23, 0.04, 0.36, col, 0.02), 0, -0.12, 0.05);
        const strap1 = box(0.2, 0.03, 0.06, "#c9894f", 0.01);
        strap1.rotation.x = 0.3;
        add(foot, strap1, 0, -0.05, 0.13);
        const strap2 = box(0.2, 0.03, 0.06, "#c9894f", 0.01);
        strap2.rotation.x = -0.2;
        add(foot, strap2, 0, -0.04, -0.02);
        add(foot, sph(0.035, "#ffffff", 8), 0, -0.03, 0.06); // shell charm
        break;
      }
      case "shoes_slippers": {
        const bread = sph(0.16, col, 14);
        bread.scale.set(0.85, 0.6, 1.3);
        add(foot, bread, 0, -0.045, 0.05);
        const crust = box(0.05, 0.04, 0.28, "#b97f45", 0.015);
        add(foot, crust, 0, -0.005, 0.05);
        break;
      }
      case "shoes_dinofeet": {
        add(foot, box(0.26, 0.12, 0.34, col, 0.05), 0, -0.08, 0.04);
        for (const tx of [-0.07, 0, 0.07]) {
          const claw = cone(0.035, 0.1, "#fff4dc", 8);
          claw.rotation.x = Math.PI / 2;
          add(foot, claw, tx, -0.09, 0.24);
        }
        break;
      }
      case "shoes_runners": {
        add(foot, box(0.24, 0.09, 0.38, "#ff5c8a", 0.035), 0, -0.095, 0.05);
        add(foot, box(0.22, 0.11, 0.32, col, 0.05), 0, -0.01, 0.04);
        add(foot, box(0.23, 0.03, 0.12, "#ffffff", 0.01), 0, -0.01, 0.12);
        const toe = sph(0.08, "#ffffff", 10);
        toe.scale.set(1.15, 0.6, 1);
        add(foot, toe, 0, -0.045, 0.19);
        break;
      }
      default: {
        add(foot, box(0.24, 0.07, 0.38, "#ffffff", 0.03), 0, -0.105, 0.05);
        add(foot, box(0.22, 0.12, 0.32, col, 0.05), 0, -0.02, 0.04);
        break;
      }
    }
  }

  /* ---------------------------------------------------------------- hat */

  private buildHat(headG: THREE.Group, cfg: AvatarConfig): void {
    if (cfg.hat === "hat_none") return;
    const col = itemColor("hat", cfg.hat, "#e85c5c");
    const g = add(headG, new THREE.Group(), 0, HEAD_CY, 0);

    switch (cfg.hat) {
      case "hat_cap": {
        const dome = mesh(new THREE.SphereGeometry(0.62, 24, 14, 0, Math.PI * 2, 0, Math.PI / 2.4), mat(col));
        add(g, dome, 0, 0.08, 0);
        const brim = box(0.5, 0.05, 0.34, col, 0.025);
        brim.rotation.x = 0.12;
        add(g, brim, 0, 0.18, 0.66);
        add(g, sph(0.05, "#ffffff", 8), 0, 0.7, 0);
        break;
      }
      case "hat_beret": {
        const b = sph(0.52, col, 18);
        b.scale.set(1.1, 0.42, 1.1);
        b.rotation.z = -0.16;
        add(g, b, 0.08, 0.55, 0);
        add(g, cyl(0.025, 0.025, 0.08, col, 8), 0.1, 0.78, 0);
        break;
      }
      case "hat_helmet": {
        const glass = sph(0.74, "#cfe8ff", 26, { transparent: true, opacity: 0.28, roughness: 0.15 });
        add(g, glass, 0, 0, 0);
        const ring = tor(0.68, 0.05, "#c5cbdb");
        ring.rotation.x = Math.PI / 2;
        add(g, ring, 0, -0.28, 0);
        add(g, cyl(0.02, 0.02, 0.18, "#c5cbdb", 8), 0, 0.74, 0);
        add(g, sph(0.06, "#ff6b6b", 10, { emissive: "#ff6b6b", emissiveIntensity: 0.6 }), 0, 0.85, 0);
        break;
      }
      case "hat_hairpin": {
        const stick = cyl(0.022, 0.022, 0.72, "#f2c14e", 8);
        stick.rotation.z = 1.15;
        add(g, stick, 0, 0.5, 0);
        const flower = add(g, new THREE.Group(), 0.36, 0.62, 0);
        for (let i = 0; i < 5; i += 1) {
          const a = (i / 5) * Math.PI * 2;
          add(flower, sph(0.05, "#f0a6c0", 8), Math.cos(a) * 0.06, Math.sin(a) * 0.06, 0);
        }
        add(flower, sph(0.035, "#f2c14e", 8), 0, 0, 0.02);
        const bead = cyl(0.012, 0.012, 0.2, "#e88f9f", 6);
        add(flower, bead, 0.02, -0.18, 0);
        add(flower, sph(0.03, "#e88f9f", 8), 0.02, -0.29, 0);
        break;
      }
      case "hat_straw": {
        add(g, cyl(0.85, 0.88, 0.045, col, 26), 0, 0.42, 0);
        const dome = sph(0.48, col, 18);
        dome.scale.set(1, 0.62, 1);
        add(g, dome, 0, 0.48, 0);
        const band = tor(0.5, 0.035, "#5aa7c9");
        band.rotation.x = Math.PI / 2;
        add(g, band, 0, 0.45, 0);
        break;
      }
      case "hat_chef": {
        add(g, cyl(0.52, 0.54, 0.16, col, 22), 0, 0.5, 0);
        const puff = sph(0.48, col, 18);
        puff.scale.set(1.05, 0.72, 1.05);
        add(g, puff, 0, 0.72, 0);
        add(g, sph(0.2, col, 12), -0.28, 0.76, 0.1);
        add(g, sph(0.2, col, 12), 0.28, 0.76, -0.05);
        break;
      }
      case "hat_dino": {
        const hood = sph(0.66, col, 22);
        hood.scale.set(1, 0.92, 0.98);
        add(g, hood, 0, 0.16, -0.06);
        const snout = box(0.34, 0.2, 0.3, col, 0.08);
        add(g, snout, 0, 0.42, 0.5);
        for (const sx of [-1, 1]) {
          add(g, sph(0.07, "#ffffff", 10), sx * 0.14, 0.52, 0.5);
          add(g, sph(0.035, "#33262b", 8), sx * 0.14, 0.52, 0.56);
        }
        for (let i = 0; i < 3; i += 1) {
          const spike = cone(0.07, 0.18, "#4f8f3f", 8);
          spike.rotation.x = -0.35;
          add(g, spike, 0, 0.78 - i * 0.2, -0.1 - i * 0.22);
        }
        break;
      }
      case "hat_headband": {
        const band = tor(0.63, 0.055, col);
        band.rotation.x = Math.PI / 2 - 0.35;
        add(g, band, 0, 0.12, 0);
        break;
      }
      case "hat_wizard": {
        const brim = cyl(0.72, 0.76, 0.045, col, 24);
        add(g, brim, 0, 0.42, 0);
        const tip = cone(0.42, 0.62, col, 20);
        tip.rotation.z = 0.14;
        add(g, tip, 0.04, 0.72, 0);
        const band = tor(0.46, 0.04, "#ffd23f");
        band.rotation.x = Math.PI / 2;
        add(g, band, 0, 0.5, 0);
        add(g, flat(starShape(0.1, 0.045), "#ffd23f", { emissive: "#ffd23f", emissiveIntensity: 0.6 }), 0.13, 0.62, 0.38);
        break;
      }
      default:
        break;
    }
  }

  /* ---------------------------------------------------------- accessory */

  private buildAccessory(body: THREE.Group, armR: THREE.Group, headG: THREE.Group, cfg: AvatarConfig): void {
    if (cfg.accessory === "acc_none") return;
    const col = itemColor("accessory", cfg.accessory, "#c9a06a");

    switch (cfg.accessory) {
      case "acc_bag": {
        add(body, box(0.3, 0.26, 0.14, col, 0.05), -0.44, 0.0, 0.05);
        const strap = box(0.05, 0.62, 0.03, "#8a6a42", 0.015);
        strap.rotation.z = 0.5;
        add(body, strap, -0.22, 0.36, 0.16);
        add(body, sph(0.03, "#f2c14e", 8), -0.44, 0.06, 0.13);
        break;
      }
      case "acc_glasses": {
        const g = add(headG, new THREE.Group(), 0, HEAD_CY, 0);
        for (const sx of [-1, 1]) {
          const rim = tor(0.115, 0.018, col);
          add(g, rim, sx * 0.215, 0.05, 0.585).rotation.y = sx * 0.2;
          const temple = box(0.02, 0.02, 0.3, col, 0.008);
          add(g, temple, sx * 0.33, 0.07, 0.42);
        }
        add(g, box(0.1, 0.02, 0.02, col, 0.008), 0, 0.08, 0.585);
        break;
      }
      case "acc_jetpack": {
        const g = add(body, new THREE.Group(), 0, 0.32, -0.42);
        add(g, box(0.36, 0.44, 0.18, col, 0.06), 0, 0, 0);
        for (const sx of [-1, 1]) {
          add(g, cyl(0.09, 0.09, 0.4, "#c5cbdb", 14), sx * 0.13, 0.02, -0.08);
          const flame = cone(0.07, 0.22, "#ff9d3f", 10, { emissive: "#ff7d2f", emissiveIntensity: 0.9 });
          flame.rotation.x = Math.PI;
          add(g, flame, sx * 0.13, -0.32, -0.08);
        }
        break;
      }
      case "acc_flute": {
        const g = add(armR, new THREE.Group(), 0, -0.5, 0.08);
        g.rotation.z = -1.15;
        g.rotation.x = 0.3;
        add(g, cyl(0.03, 0.03, 0.52, col, 10), 0, 0, 0);
        add(g, sph(0.04, "#d8b04f", 8), 0, 0.28, 0);
        for (let i = 0; i < 4; i += 1) add(g, cyl(0.032, 0.032, 0.015, "#8a6a42", 8), 0, 0.14 - i * 0.08, 0);
        break;
      }
      case "acc_float": {
        const g = add(body, new THREE.Group(), 0, -0.08, 0);
        const ring = tor(0.42, 0.15, col);
        ring.rotation.x = Math.PI / 2;
        add(g, ring, 0, 0, 0);
        for (let i = 0; i < 4; i += 1) {
          const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
          const stripe = box(0.12, 0.1, 0.32, "#ffffff", 0.03);
          stripe.rotation.y = a;
          add(g, stripe, Math.sin(a) * 0.42, 0, Math.cos(a) * 0.42);
        }
        // duck head
        add(g, sph(0.11, col, 12), 0, 0.2, 0.45);
        const beak = cone(0.045, 0.1, "#f2a03f", 8);
        beak.rotation.x = Math.PI / 2;
        add(g, beak, 0, 0.19, 0.58);
        break;
      }
      case "acc_whisk": {
        const g = add(armR, new THREE.Group(), 0, -0.56, 0.05);
        add(g, cyl(0.035, 0.04, 0.22, "#c9894f", 10), 0, 0, 0);
        for (let i = 0; i < 3; i += 1) {
          const loop = tor(0.09, 0.012, col);
          loop.rotation.y = (i / 3) * Math.PI;
          loop.scale.set(0.6, 1.4, 1);
          add(g, loop, 0, -0.22, 0);
        }
        break;
      }
      case "acc_dinotail": {
        const g = add(body, new THREE.Group(), 0, -0.05, -0.26);
        let z = 0;
        let y = 0;
        for (let i = 0; i < 4; i += 1) {
          add(g, sph(0.17 - i * 0.035, col, 12), 0, y, z);
          z -= 0.19;
          y -= 0.07;
        }
        for (let i = 0; i < 3; i += 1) {
          const spike = cone(0.045, 0.12, "#4f8f3f", 8);
          spike.rotation.x = -0.6;
          add(g, spike, 0, y + 0.55 + i * 0.02 - 0.42, z + 0.5 - i * 0.19);
        }
        break;
      }
      case "acc_basketball": {
        const g = add(armR, new THREE.Group(), 0, -0.66, 0.08);
        add(g, sph(0.22, col, 20), 0, 0, 0);
        const seam1 = tor(0.222, 0.012, "#59372d");
        add(g, seam1, 0, 0, 0);
        const seam2 = tor(0.222, 0.012, "#59372d");
        seam2.rotation.x = Math.PI / 2;
        add(g, seam2, 0, 0, 0);
        break;
      }
      case "acc_wand": {
        const g = add(armR, new THREE.Group(), 0, -0.52, 0.06);
        g.rotation.z = -0.4;
        add(g, cyl(0.022, 0.026, 0.44, col, 10), 0, 0.1, 0);
        add(g, flat(starShape(0.11, 0.05), "#ffd23f", { emissive: "#ffd23f", emissiveIntensity: 0.9 }), 0, 0.4, 0.01);
        add(g, sph(0.05, "#fff3b8", 10, { emissive: "#ffe98a", emissiveIntensity: 0.9 }), 0, 0.4, 0);
        break;
      }
      default:
        break;
    }
  }
}
